<script setup lang="ts">
import { ref,onMounted,onBeforeUnmount,nextTick } from 'vue'
import type { Artwork } from './types'
import { assetUrl } from './types'
import { createMuseum } from './museum/Museum'
import ArtworkDetail from './components/ArtworkDetail.vue'
const host=ref<HTMLElement>();const artworks=ref<Artwork[]>([]);const selected=ref<Artwork|null>(null);const loaded=ref(0);const error=ref('');const notices=ref<string[]>([]);const ready=ref(false);const intro=ref(false)
let museum:ReturnType<typeof createMuseum>|undefined;const abort=new AbortController()
function reload(){window.location.reload()}
function close(){selected.value=null;museum?.clear()}
function reset(){selected.value=null;museum?.reset()}
function key(e:KeyboardEvent){if(e.key==='Escape')close()}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{notices.value=['浏览器未允许全屏，请使用浏览器全屏功能。']}}
onMounted(async()=>{window.addEventListener('keydown',key);try{const response=await fetch(assetUrl('artworks.json'),{signal:abort.signal});if(!response.ok)throw Error('馆藏数据暂时无法加载');const data=await response.json();if(!Array.isArray(data)||!data.length)throw Error('当前暂无可展示的馆藏');if(!data.every(a=>a.id&&a.title&&/^artworks\/[a-z0-9-]+\.jpg$/.test(a.image)&&/^https:\/\/www\.metmuseum\.org\/art\/collection\/search\/\d+$/.test(a.source_url)&&a.width>0&&a.height>0)||new Set(data.map(a=>a.id)).size!==data.length)throw Error('馆藏数据格式异常');artworks.value=data;await nextTick();if(abort.signal.aborted)return;museum=createMuseum(host.value!,data,a=>selected.value=a,n=>loaded.value=n,title=>notices.value.push(`图片暂未加载：${title}`));ready.value=true}catch(e){if(!abort.signal.aborted)error.value=e instanceof Error?e.message:'无法初始化3D展厅，请检查浏览器是否支持 WebGL'}})
onBeforeUnmount(()=>{abort.abort();museum?.dispose();window.removeEventListener('keydown',key)})
</script>
<template><main :class="{ 'has-detail':selected }"><header><div class="brand-mark" aria-hidden="true">❖</div><div class="brand"><h1>唐卡数字展馆</h1><p>TANGKA DIGITAL MUSEUM</p></div><div class="header-caption">一方画境 · 万象于心 <span>THE ART OF CONTEMPLATION</span></div><nav><button @click="reset" :disabled="!ready">↺ <span>初始视角</span></button><button @click="fullscreen">⛶ <span>全屏</span></button></nav></header><section class="stage"><div ref="host" class="canvas-host" :aria-busy="!ready"></div><div class="exhibition-heading"><p class="eyebrow">THE PERMANENT COLLECTION / 01</p><h2>观境<span>·</span>唐卡艺术</h2><p>循光而行，走近画中世界</p></div><aside class="navigation"><p class="eyebrow">EXPLORE / 展厅导览</p><button class="hall active" @click="reset"><span>01</span> 唐卡艺术厅 <small>{{ artworks.length }} 件开放馆藏</small></button><button class="intro-toggle" @click="intro=!intro" :aria-expanded="intro">展馆介绍 {{ intro?'−':'+' }}</button><p v-if="intro" class="intro">以三维空间呈现大都会艺术博物馆的开放馆藏。八件作品涵盖不同题材与材质；建筑与纹样为本项目的数字空间设计，并非历史建筑复原。</p><div class="collection-index"><button v-for="(a,i) in artworks" :key="a.id" :class="{chosen:selected?.id===a.id}" @click="museum?.select(a.id)" :title="a.title"><span>{{ String(i+1).padStart(2,'0') }}</span>{{ a.title }}</button></div><p class="navigation-note">THE MET · OPEN ACCESS<br>真实馆藏 / 数字呈现</p></aside><div v-if="error" class="status error" role="alert"><h2>展厅暂时无法打开</h2><p>{{ error }}</p><button @click="reload">重新加载</button></div><div v-else-if="!ready" class="status" role="status">正在开启展厅…</div><p v-if="ready&&loaded<artworks.length" class="loading" role="status">馆藏图像载入 {{ loaded }} / {{ artworks.length }}</p><p v-if="notices.length" class="notice" role="status">{{ notices.join('；') }}</p><div class="zoom-controls" aria-label="视角控制"><button @click="museum?.zoom(.82)" aria-label="放大" :disabled="!ready">＋</button><span></span><button @click="museum?.zoom(1.22)" aria-label="缩小" :disabled="!ready">−</button><span></span><button @click="reset" aria-label="恢复初始视角" :disabled="!ready">↺</button></div><div class="space-label">第一展厅 <span>HALL 01</span></div><ArtworkDetail v-if="selected" :artwork="selected" @close="close"/></section><footer><div class="instructions"><span>左键拖动 · 旋转</span><span>滚轮 · 缩放</span><span>右键拖动 · 平移</span><span>点击作品 · 鉴赏</span></div><p class="selected-title">{{ selected?.title || '自由观展，静心入境' }}</p><p class="count"><b>{{ String(artworks.length).padStart(2,'0') }}</b> 件馆藏 <span>·</span> 01 展厅</p></footer></main></template>
